import { defineConfig } from '@playwright/test'

const preview = process.env.MD_MANAGER_TEST_PREVIEW === '1'
const baseURL = `http://127.0.0.1:${process.env.MD_MANAGER_WEB_PORT ?? (preview ? 4173 : 5173)}`

export default defineConfig({
  testDir: './tests',
  testMatch: '**/*.spec.ts',
  // Browser tests mutate (and then clean) the shared fixture tree, so they must never run concurrently.
  workers: 1,
  fullyParallel: false,
  use: {
    baseURL,
    browserName: 'chromium',
    // Reduced motion makes the force layout settle synchronously, so nothing waits on animation.
    reducedMotion: 'reduce',
  },
  webServer: [
    {
      command: 'npm run start:api',
      url: `http://127.0.0.1:${process.env.MD_MANAGER_API_PORT ?? 3001}/api/entries`,
      reuseExistingServer: false,
      timeout: 30_000,
    },
    {
      command: preview ? 'npm run preview' : 'npm run dev:web',
      url: baseURL,
      reuseExistingServer: false,
      timeout: 30_000,
    },
  ],
})

import { useMemo, useState, type FormEvent } from 'react'
import { nodeId, type FolderRef, type Source, type TreeIndex } from '../graph/model.ts'
import { Modal } from '../ui/Modal.tsx'
import { OperationError, performOperation, type MutationRequest, type MutationResponse } from './api.ts'
import { validateName } from './validate.ts'

/** What the user asked to do and to what. Folders use `kind: 'folder'`; a source root is a folder with path ''. */
export type OperationTarget =
  | { kind: 'folder'; ref: FolderRef }
  | { kind: 'file'; ref: { source: Source; path: string }; draftDirty: boolean }

export type Operation =
  | { op: 'create-file' | 'create-folder'; parent: FolderRef }
  | { op: 'rename' | 'move' | 'delete'; target: OperationTarget }
  | { op: 'copy'; target: Extract<OperationTarget, { kind: 'file' }> }

type Props = {
  operation: Operation
  index: TreeIndex
  onCancel: () => void
  onSuccess: (operation: Operation, response: MutationResponse) => void
}

function baseName(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

function parentPath(path: string): string {
  const cut = path.lastIndexOf('/')
  return cut === -1 ? '' : path.slice(0, cut)
}

function describeFolder(ref: FolderRef): string {
  return ref.path ? `${ref.source} / ${ref.path}` : ref.source
}

function joinPath(parent: string, name: string): string {
  return parent ? `${parent}/${name}` : name
}

/** Folders of one source, in listing order, optionally excluding a subtree (a folder cannot move into itself). */
function folderOptions(index: TreeIndex, source: Source, exclude: string | null): FolderRef[] {
  const options: FolderRef[] = []
  for (const node of index.nodes.values()) {
    if (node.source !== source || node.kind === 'file') continue
    if (exclude !== null && (node.path === exclude || node.path.startsWith(`${exclude}/`))) continue
    options.push({ source, path: node.path })
  }
  return options.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
}

const TITLES: Record<Operation['op'], string> = {
  'create-file': 'New file', 'create-folder': 'New folder', rename: 'Rename', move: 'Move', delete: 'Delete', copy: 'Copy',
}
const SUBMIT: Record<Operation['op'], string> = {
  'create-file': 'Create', 'create-folder': 'Create', rename: 'Rename', move: 'Move', delete: 'Delete', copy: 'Copy',
}

/** One labelled dialog per operation: name/destination fields, client validation, one pending request, server errors inline. */
export function OperationDialog({ operation, index, onCancel, onSuccess }: Props) {
  const { op } = operation
  const target = 'target' in operation ? operation.target : null
  const targetName = target ? baseName(target.ref.path) : ''
  const nameKind: 'file' | 'folder' = op === 'create-folder' || (target?.kind === 'folder') ? 'folder' : 'file'
  const [name, setName] = useState(op === 'rename' || op === 'copy' ? targetName : '')
  const destinationSource: Source | null = op === 'copy' ? (operation.target.ref.source === 'Pi' ? 'Claude' : 'Pi') : op === 'move' ? operation.target.ref.source : null
  const destinations = useMemo(() => {
    if (!destinationSource) return []
    const exclude = op === 'move' && operation.target.kind === 'folder' ? operation.target.ref.path : null
    const currentParent = op === 'move' ? parentPath(operation.target.ref.path) : null
    return folderOptions(index, destinationSource, exclude).filter(folder => folder.path !== currentParent)
  }, [destinationSource, index, op, operation])
  const [destination, setDestination] = useState(() => destinations[0]?.path ?? '')
  const [error, setError] = useState<string | null>(null)
  const [pending, setPending] = useState(false)

  const request = (): MutationRequest | string => {
    switch (op) {
      case 'create-file':
      case 'create-folder': {
        const invalid = validateName(name, nameKind)
        if (invalid) return invalid
        return { op, source: operation.parent.source, path: joinPath(operation.parent.path, name) }
      }
      case 'rename': {
        const invalid = validateName(name, nameKind)
        if (invalid) return invalid
        if (name === targetName) return 'Enter a different name.'
        return { op, source: operation.target.ref.source, path: operation.target.ref.path, destinationPath: joinPath(parentPath(operation.target.ref.path), name) }
      }
      case 'move': {
        if (destinations.length === 0) return 'There is no other folder to move this into.'
        return { op, source: operation.target.ref.source, path: operation.target.ref.path, destinationPath: joinPath(destination, targetName) }
      }
      case 'delete':
        return { op, source: operation.target.ref.source, path: operation.target.ref.path }
      case 'copy': {
        const invalid = validateName(name, 'file')
        if (invalid) return invalid
        return { op, source: operation.target.ref.source, path: operation.target.ref.path, destinationSource: destinationSource!, destinationPath: joinPath(destination, name) }
      }
    }
  }

  const submit = async (event: FormEvent) => {
    event.preventDefault()
    if (pending) return
    const built = request()
    if (typeof built === 'string') { setError(built); return }
    setError(null)
    setPending(true)
    try {
      const response = await performOperation(built)
      onSuccess(operation, response)
    } catch (failure) {
      setError(failure instanceof OperationError ? failure.message : 'The operation failed unexpectedly.')
      setPending(false)
    }
  }

  let description: React.ReactNode
  let fields: React.ReactNode = null
  const destinationField = destinationSource && (
    <label className="field">
      <span>Destination folder</span>
      <select value={destination} onChange={event => setDestination(event.target.value)} disabled={pending || destinations.length === 0} aria-label="Destination folder">
        {destinations.map(folder => (
          <option key={nodeId(folder.source, folder.path)} value={folder.path}>{folder.path || `${folder.source} (source root)`}</option>
        ))}
      </select>
    </label>
  )
  switch (op) {
    case 'create-file':
    case 'create-folder':
      description = <p>In <span className="dialog-path">{describeFolder(operation.parent)}</span>. {op === 'create-file' ? 'The file starts empty and opens for editing.' : 'The folder starts empty.'}</p>
      fields = (
        <label className="field">
          <span>{op === 'create-file' ? 'File name' : 'Folder name'}</span>
          <input type="text" value={name} onChange={event => setName(event.target.value)} disabled={pending} placeholder={op === 'create-file' ? 'name.md' : 'name'} autoComplete="off" spellCheck={false} />
        </label>
      )
      break
    case 'rename':
      description = <p>Renames <span className="dialog-path">{describeFolder({ source: operation.target.ref.source, path: operation.target.ref.path })}</span> within its folder.</p>
      fields = (
        <label className="field">
          <span>New name</span>
          <input type="text" value={name} onChange={event => setName(event.target.value)} disabled={pending} autoComplete="off" spellCheck={false} />
        </label>
      )
      break
    case 'move':
      description = <p>Moves <span className="dialog-path">{describeFolder({ source: operation.target.ref.source, path: operation.target.ref.path })}</span> to another folder in {operation.target.ref.source}, keeping its name.</p>
      fields = destinationField
      break
    case 'delete':
      description = (
        <>
          <p>Delete <span className="dialog-path">{operation.target.ref.source} / {operation.target.ref.path}</span>?</p>
          <p>This cannot be undone in the app: there is no trash or version history, only whatever git or backups hold. {operation.target.kind === 'folder' ? 'Only an empty folder can be deleted.' : ''}</p>
        </>
      )
      break
    case 'copy':
      description = (
        <>
          <p>Copies the <strong>saved content</strong> of <span className="dialog-path">{operation.target.ref.source} / {operation.target.ref.path}</span> from disk into {destinationSource}{operation.target.draftDirty ? '; unsaved draft changes are not included' : ''}.</p>
          <p>The bytes are copied as they are, so frontmatter written for {operation.target.ref.source} may not be accepted by the {destinationSource} agent.</p>
        </>
      )
      fields = (
        <>
          {destinationField}
          <label className="field">
            <span>File name</span>
            <input type="text" value={name} onChange={event => setName(event.target.value)} disabled={pending} autoComplete="off" spellCheck={false} />
          </label>
        </>
      )
      break
  }

  const destructive = op === 'delete'
  return (
    <Modal title={op === 'copy' ? `Copy to ${destinationSource}` : TITLES[op]} initialFocus={fields ? 'first-field' : destructive ? 'cancel' : 'confirm'} onCancel={onCancel}>
      <form method="dialog" onSubmit={event => { void submit(event) }} aria-busy={pending}>
        <div className="confirm-description">{description}</div>
        {fields}
        {error && <p className="dialog-error" role="alert">{error}</p>}
        <div className="confirm-actions">
          <button type="button" className="button" data-dialog-cancel onClick={onCancel} disabled={pending}>Cancel</button>
          <button type="submit" className={destructive ? 'button button-danger' : 'button'} data-dialog-confirm disabled={pending} aria-busy={pending}>
            {pending ? `${SUBMIT[op]}…` : SUBMIT[op]}
          </button>
        </div>
      </form>
    </Modal>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import type { FileRef } from '../graph/model.ts'
import { fetchDocument } from './api.ts'
import { ConfirmDialog } from './ConfirmDialog.tsx'
import { Editor } from './Editor.tsx'
import { hasUnacknowledgedWork, isPending, type Snapshot } from './editSession.ts'
import type { TextAnalysis } from './serialize.ts'
import { useEditSession } from './useEditSession.ts'

/** What the rest of the app needs to know to guard navigation and refuse operations on the active file. */
export type EditingState = { dirty: boolean; pending: boolean; conflicted: boolean }

type Props = {
  fileRef: FileRef
  document: Snapshot
  analysis: TextAnalysis
  onAnnounce: (message: string) => void
  onStateChange: (state: EditingState | null) => void
  /** The last acknowledged content/hash (initial read, each successful save or revert, each reload). */
  onAcknowledged: (acknowledged: Snapshot) => void
  /** Runs `leave` now, or after the user confirms discarding a dirty draft; refuses while a save is pending. */
  guardLeave: (leave: () => void) => void
  /** Leaves editing mode; `acknowledged` is what the read-only view should now show. */
  onExit: (acknowledged: Snapshot) => void
}

type Confirmation = 'reload' | 'revert' | null

function fileName(ref: FileRef): string {
  return ref.path.slice(ref.path.lastIndexOf('/') + 1)
}

export function EditingSession({ fileRef, document, analysis, onAnnounce, onStateChange, onAcknowledged, guardLeave, onExit }: Props) {
  const name = fileName(fileRef)
  const { session, edit, save, revert, reload } = useEditSession(fileRef, document, {
    onSaved: purpose => onAnnounce(purpose === 'revert' ? `Reverted ${name} to the version from when editing began.` : `Saved ${name}.`),
    onFailed: (error, purpose) => onAnnounce(error.kind === 'conflict'
      ? `${purpose === 'revert' ? 'Revert' : 'Save'} conflicted: ${name} changed on disk.`
      : `${purpose === 'revert' ? 'Revert' : 'Save'} failed for ${name}.`),
  })

  const dirty = hasUnacknowledgedWork(session)
  const pending = isPending(session)
  const conflicted = session.conflicted
  useEffect(() => { onStateChange({ dirty, pending, conflicted }) }, [dirty, pending, conflicted, onStateChange])
  useEffect(() => () => onStateChange(null), [onStateChange])
  useEffect(() => { onAcknowledged(session.acknowledged) }, [session.acknowledged, onAcknowledged])

  const sessionRef = useRef(session)
  useEffect(() => { sessionRef.current = session })

  const [confirmation, setConfirmation] = useState<Confirmation>(null)
  const [reloading, setReloading] = useState(false)
  const [fallback, setFallback] = useState<string | null>(null)

  const performReload = useCallback(async () => {
    setReloading(true)
    onAnnounce(`Reloading ${name} from disk.`)
    try {
      const fresh = await fetchDocument(fileRef)
      reload({ content: fresh.content, hash: fresh.hash })
      setConfirmation(null)
      onAnnounce(`Reloaded ${name} from disk. Editing starts again from this version.`)
    } catch {
      setConfirmation(null)
      onAnnounce(`Reloading ${name} failed. The draft and the conflict are unchanged.`)
    } finally { setReloading(false) }
  }, [fileRef, name, onAnnounce, reload])

  const copyDraft = useCallback(async () => {
    const draft = sessionRef.current.draft
    try {
      await navigator.clipboard.writeText(draft)
      setFallback(null)
      onAnnounce('Draft copied to the clipboard.')
    } catch {
      setFallback(draft)
      onAnnounce('The clipboard is unavailable. The draft is shown as selectable text.')
    }
  }, [onAnnounce])

  const exitEditing = useCallback(() => {
    guardLeave(() => onExit(sessionRef.current.acknowledged))
  }, [guardLeave, onExit])

  const recovery = fallback !== null ? (
    <div className="editor-fallback">
      <p id="draft-fallback-help">The clipboard is unavailable. Select the text below and copy it yourself.</p>
      <textarea aria-label="Draft text" aria-describedby="draft-fallback-help" readOnly value={fallback} rows={6} onFocus={event => event.currentTarget.select()} />
      <p className="document-actions"><button type="button" className="button" onClick={() => setFallback(null)}>Hide draft text</button></p>
    </div>
  ) : null

  return (
    <>
      <Editor
        fileRef={fileRef}
        session={session}
        analysis={analysis}
        onEdit={edit}
        onSave={save}
        onRevert={() => setConfirmation('revert')}
        onReload={() => setConfirmation('reload')}
        onCopyDraft={() => { void copyDraft() }}
        onExit={exitEditing}
        recovery={recovery}
      />
      {confirmation === 'reload' && (
        <ConfirmDialog title="Reload from disk?" confirmLabel="Reload" destructive pending={reloading} onConfirm={() => { void performReload() }} onCancel={() => setConfirmation(null)}>
          <p>Reloading {name} will discard your current draft and replace it with the version now on disk. Copy the draft first if you want to keep it.</p>
        </ConfirmDialog>
      )}
      {confirmation === 'revert' && (
        <ConfirmDialog title="Revert to the version from when editing began?" confirmLabel="Revert" destructive onConfirm={() => { setConfirmation(null); revert() }} onCancel={() => setConfirmation(null)}>
          <p>This will discard your current draft changes and save the content {name} had when you pressed Edit, replacing every save made since. It is checked against the last acknowledged version and can report a conflict.</p>
        </ConfirmDialog>
      )}
    </>
  )
}

    if (target) {
      // Do not let keyboard-focus reveal or native scrolling alter a restored viewport/outline scroll.
      target.setAttribute('data-restoring-focus', 'true')
      target.focus({ preventScroll: true })
      target.removeAttribute('data-restoring-focus')
      pendingFocus.current = null
    }
  })

  // ---- File and folder operations ----
  const [operation, setOperation] = useState<Operation | null>(null)
  const [operationNotice, setOperationNotice] = useState<string | null>(null)
  const [outcome, setOutcome] = useState<{ message: string; refreshFailed: boolean } | null>(null)
  const requestFolderOperation = useCallback((op: 'create-file' | 'create-folder' | 'rename' | 'move' | 'delete') => {
    const current = locationRef.current
    const ref: FolderRef | null = current.kind === 'folder' ? current.ref : null
    if (!ref) return
    setOperationNotice(null)
    if (op === 'create-file' || op === 'create-folder') setOperation({ op, parent: ref })
    else if (ref.path) setOperation({ op, target: { kind: 'folder', ref } })
  }, [])
  const requestFileOperation = useCallback((op: 'rename' | 'move' | 'delete' | 'copy') => {
    const current = locationRef.current
    if (current.kind !== 'file') return
    const editing = editingRef.current
    const name = fileName(current.ref)
    if (op !== 'copy' && editing && (editing.dirty || editing.pending || editing.conflicted)) {
      const reason = editing.pending ? 'a save is still pending' : editing.conflicted ? 'its draft conflicts with the file on disk' : 'it has unsaved changes'
      setOperationNotice(`${name} cannot be ${op === 'delete' ? 'deleted' : `${op}d`} while ${reason}. Save or discard the draft first; nothing is saved or discarded for you.`)
      setAnnouncement(`${name} has unsaved changes. Save or discard them first.`)
      return
    }
    if (op === 'copy' && editing?.pending) return
    setOperationNotice(null)
    const target = { kind: 'file' as const, ref: current.ref, draftDirty: editing?.dirty === true }
    setOperation(op === 'copy' ? { op, target } : { op, target })
  }, [])
  const openCreatedFile = useCallback((ref: FileRef) => {
    const origin = saveBrowsingRef.current(null)
    pendingFocus.current = null
    writeHistory({ origin }, fileToPathname(ref))
    setLocation({ kind: 'file', ref })
  }, [writeHistory])
  const completeOperation = useCallback(async (done: Operation, response: MutationResponse) => {
    setOperation(null)
    const source = response.source
    const name = fileName({ source, path: response.path })
    const where = (path: string) => (path ? `${source} / ${path}` : source)
    let message: string
    // Identity changes of the open document are applied first so the document view never shows a stale path.
    if ((done.op === 'rename' || done.op === 'move') && done.target.kind === 'file' && response.destinationPath) {
      const ref: FileRef = { source, path: response.destinationPath }
      const entry = historyEntries.current.get(historyKey.current)
      writeHistory({ origin: entry?.origin }, fileToPathname(ref), true)
      setLocation({ kind: 'file', ref })
    }
    const index = await reloadListing()
    switch (done.op) {
      case 'create-file': {
        message = `Created ${name} in ${where(response.path.slice(0, Math.max(0, response.path.lastIndexOf('/'))))}.`
        openCreatedFile({ source, path: response.path })
        break
      }
      case 'create-folder': {
        message = `Created folder ${name} in ${where(response.path.slice(0, Math.max(0, response.path.lastIndexOf('/'))))}.`
        if (index) navigate({ source, path: response.path }, { reveal: true })
        break
      }
      case 'rename':
      case 'move': {
        message = `${done.op === 'rename' ? 'Renamed' : 'Moved'} ${name} to ${where(response.destinationPath ?? response.path)}.`
        if (done.target.kind === 'folder' && response.destinationPath) navigate({ source, path: response.destinationPath }, { replace: true, reveal: true })
        break
      }
      case 'delete': {
        message = `Deleted ${name} from ${where(response.path.slice(0, Math.max(0, response.path.lastIndexOf('/'))))}.`
        const parent: FolderRef = { source, path: response.path.slice(0, Math.max(0, response.path.lastIndexOf('/'))) }
        pendingFocus.current = refId(parent)
        navigate(parent, { reveal: true })
        break
      }
      case 'copy':
        message = `Copied ${name} to ${response.destinationSource} / ${response.destinationPath}.`
        break
    }
    setOutcome({ message, refreshFailed: index === null })
    setAnnouncement(index === null ? `${message} The listing could not be refreshed.` : message)
  }, [navigate, openCreatedFile, reloadListing, writeHistory])

  const index = data.status === 'ready' ? data.index : null
  const selectedRef = location.kind === 'folder' ? location.ref : null
  const selectedExists = index !== null && selectedRef !== null && folderExists(index, selectedRef)
  const selectedId = selectedExists && selectedRef ? refId(selectedRef) : null
  const visible = useMemo(() => (index ? visibleGraph(index, expanded) : { nodes: [], edges: [] }), [index, expanded])

  const select = useCallback((node: GraphNode) => {
    const ref = { source: node.source, path: node.path }
    if (sameRef(locationRef.current.kind === 'folder' ? locationRef.current.ref : null, ref)) return
    navigate(ref)
  }, [navigate])

  const toggleExpand = useCallback((node: GraphNode) => {
    if (!index) return
    if (expanded.has(node.id)) {
      setExpanded(collapseNode(index, expanded, node.id))
      const current = locationRef.current
      if (current.kind === 'folder' && descendantIds(index, node.id).includes(refId(current.ref))) {
        navigate({ source: node.source, path: node.path }, { replace: true })
      }
      setAnnouncement(`Collapsed ${node.name}.`)
    } else {
      setExpanded(new Set(expanded).add(node.id))
      setAnnouncement(`Expanded ${node.name}: ${describeCounts(childCounts(index, node.id))}`)
    }
  }, [index, expanded, navigate])

